  "inlineSchema": "// AutoRevive AI Prisma Schema\n// Provider configured for SQLite by default for instant zero-dependency execution.\n// Can be changed to \"mysql\" for production MySQL database.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Customer {\n  id                 String            @id @default(uuid())\n  razorpayCustomerId String            @unique\n  name               String\n  email              String\n  phone              String\n  status             String            @default(\"ACTIVE\") // ACTIVE, FLAGGED, INACTIVE\n  createdAt          DateTime          @default(now())\n  updatedAt          DateTime          @updatedAt\n  transactions       Transaction[]\n  notifications      NotificationLog[]\n\n  @@map(\"customers\")\n}\n\nmodel Transaction {\n  id                String   @id @default(uuid())\n  razorpayPaymentId String   @unique\n  razorpayOrderId   String?\n  customerId        String\n  customer          Customer @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  amount            Float\n  currency          String   @default(\"INR\")\n  status            String // PENDING, CAPTURED, FAILED, RECOVERED, REFUNDED\n  paymentMethod     String // CARD, UPI, NETBANKING, WALLET, EMI\n  failureReason     String?\n  failureCode       String?\n  failureCategory   String? // INSUFFICIENT_FUNDS, BANK_TIMEOUT, GATEWAY_TIMEOUT, EXPIRED_CARD, NETWORK_ERROR, SUSPECTED_FRAUD\n  recoveryStatus    String   @default(\"NOT_STARTED\") // NOT_STARTED, IN_RECOVERY, RECOVERED, FAILED_RECOVERY, EXPIRED, STOPPED\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  failureLogs       FailureLog[]\n  workflows         RecoveryWorkflow[]\n  retryAttempts     RetryAttempt[]\n  notifications     NotificationLog[]\n  revenueRecoveries RevenueRecovery[]\n\n  @@map(\"transactions\")\n}\n\nmodel FailureLog {\n  id                  String      @id @default(uuid())\n  transactionId       String\n  transaction         Transaction @relation(fields: [transactionId], references: [id], onDelete: Cascade)\n  rawError            String // Raw JSON or payload snippet\n  errorCode           String\n  errorMessage        String\n  aiDiagnosis         String // LLM/Heuristic explanation\n  recoveryProbability Float // 0 - 100 percentage\n  riskScore           Float // 0 - 100 risk rating\n  category            String // Failure taxonomy category\n  createdAt           DateTime    @default(now())\n\n  @@map(\"failure_logs\")\n}\n\nmodel RecoveryWorkflow {\n  id               String      @id @default(uuid())\n  transactionId    String\n  transaction      Transaction @relation(fields: [transactionId], references: [id], onDelete: Cascade)\n  status           String      @default(\"PENDING\") // PENDING, ACTIVE, COMPLETED, FAILED, CANCELLED\n  decision         String // RETRY_NOW, RETRY_LATER, CUSTOMER_ACTION, STOP_RETRY, MANUAL_REVIEW\n  totalRetries     Int         @default(0)\n  maxRetries       Int         @default(3)\n  nextRetryAt      DateTime?\n  confidenceScore  Float // 0 - 100\n  recoveryStrategy String // Description of the backoff/decay strategy\n  createdAt        DateTime    @default(now())\n  updatedAt        DateTime    @updatedAt\n\n  retryAttempts RetryAttempt[]\n\n  @@map(\"recovery_workflows\")\n}\n\nmodel RetryAttempt {\n  id              String           @id @default(uuid())\n  transactionId   String\n  transaction     Transaction      @relation(fields: [transactionId], references: [id], onDelete: Cascade)\n  workflowId      String\n  workflow        RecoveryWorkflow @relation(fields: [workflowId], references: [id], onDelete: Cascade)\n  attemptNumber   Int\n  scheduledAt     DateTime\n  executedAt      DateTime?\n  status          String           @default(\"SCHEDULED\") // SCHEDULED, EXECUTED, SUCCESS, FAILED, CANCELLED\n  responseCode    String?\n  responseMessage String?\n  outcome         String? // SUCCESS, DECLINED, TIMEOUT\n  createdAt       DateTime         @default(now())\n\n  @@map(\"retry_attempts\")\n}\n\nmodel NotificationLog {\n  id            String      @id @default(uuid())\n  customerId    String\n  customer      Customer    @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  transactionId String\n  transaction   Transaction @relation(fields: [transactionId], references: [id], onDelete: Cascade)\n  channel       String // EMAIL, SMS, WHATSAPP, IN_APP\n  type          String // FAILURE_ALERT, RECOVERY_ACTION_LINK, SUCCESS_RECEIPT\n  status        String      @default(\"SENT\") // DELIVERED, SENT, FAILED\n  recipient     String\n  messageBody   String\n  sentAt        DateTime    @default(now())\n  createdAt     DateTime    @default(now())\n\n  @@map(\"notification_logs\")\n}\n\nmodel RevenueRecovery {\n  id              String      @id @default(uuid())\n  transactionId   String\n  transaction     Transaction @relation(fields: [transactionId], references: [id], onDelete: Cascade)\n  originalAmount  Float\n  recoveredAmount Float\n  recoveredAt     DateTime    @default(now())\n  recoveryMethod  String // SMART_RETRY, CUSTOMER_ACTION_LINK, MANUAL_OVERRIDE\n  costSaved       Float       @default(0.0) // Estimated revenue saved minus processing fee\n  createdAt       DateTime    @default(now())\n\n  @@map(\"revenue_recoveries\")\n}\n\nmodel WebhookEvent {\n  id          String   @id @default(uuid())\n  eventId     String   @unique // Razorpay event ID e.g. event_12345\n  eventType   String // payment.failed, payment.captured, subscription.charged\n  payload     String // Raw JSON string\n  status      String   @default(\"PROCESSED\") // RECEIVED, PROCESSED, FAILED\n  processedAt DateTime @default(now())\n  createdAt   DateTime @default(now())\n\n  @@map(\"webhook_events\")\n}\n",
